"""Enable PyTorch memory-efficient attention without changing model inputs."""

import sys

import torch
import torch.nn.functional as F
from torch.nn.attention import SDPBackend, sdpa_kernel

from baichuan_runtime import BaichuanRuntime as OriginalRuntime, _extract_audio


def efficient_attention(self, q, k, v, *args, use_flash=True, **kwargs):
    if use_flash:
        return self._socialomni_original_forward(q, k, v, *args, use_flash=True, **kwargs)
    with sdpa_kernel([SDPBackend.FLASH_ATTENTION, SDPBackend.EFFICIENT_ATTENTION]):
        result = F.scaled_dot_product_attention(q, k, v, *args, **kwargs)
    return result.transpose(1, 2)


class BaichuanRuntime(OriginalRuntime):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        patched = 0
        for module in list(sys.modules.values()):
            if module is None or not getattr(module, "__name__", "").endswith(".sequence_parallel_utils"):
                continue
            attention = getattr(module, "LocalAttention", None)
            if attention is None:
                continue
            if not hasattr(attention, "_socialomni_original_forward"):
                attention._socialomni_original_forward = attention.forward
                attention.forward = efficient_attention
            patched += 1
        if not patched:
            raise RuntimeError("Baichuan LocalAttention module was not found")
